#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""V363 — نصب‌کنندهٔ خودکفا (نسخهٔ ۳).

این فایل **خودش پچ را درون دارد**؛ دیگر لازم نیست فایل .patch را دانلود یا
کنارش بگذارید و امکان «فایل اشتباه» وجود ندارد.

    python3 V363_install.py                      # فقط بررسی و اعمال، بدون کامیت
    python3 V363_install.py --commit --push      # اعمال + کامیت + push

مسیر مخزن پیش‌فرض: پوشه‌ای که اسکریپت در آن است؛ با --repo عوض می‌شود.
"""

import argparse
import base64
import hashlib
import pathlib
import subprocess
import sys
import tempfile

PATCH_SHA256 = "f014a144d8ae0b479aaf40d54b26fb895fce2065710b45974cd9a27194938dfb"
PATCH_BYTES = 140211
VERSION_WANTED = "1.03.93"

ARTIFACT_NAMES = {"V363_doctor.py", "V363_install.py", ".DS_Store", "nohup.out"}
ARTIFACT_SUFFIXES = (".patch", ".diff", ".rej", ".orig", ".log")

MARKERS = [
    ("نسخهٔ اپ 1.03.93", "text/APP_VERSION.txt", lambda s: s.strip().startswith(VERSION_WANTED)),
    ("بلوک تازهٔ CHANGELOG", "text/CHANGELOG_FA.txt", lambda s: s.strip().startswith("V363")),
    ("پل متن displayText", "app/src/main/java/ir/exam/app/domain/bank/ReferenceBankModels.kt",
     lambda s: "fun displayText(text: String, qHtml: String, limit: Int = 0)" in s),
    ("متن بدون شکستن نیم‌فاصله", "app/src/main/java/ir/exam/app/domain/bank/ReferenceBankModels.kt",
     lambda s: "fun htmlToText(html: String): String" in s),
    ("بستن فرمول باز", "app/src/main/java/ir/exam/app/domain/bank/ReferenceBankModels.kt",
     lambda s: "fun balanceMath(value: String): String" in s),
    ("کلید شارد v3630", "app/src/main/java/ir/exam/app/domain/bank/ReferenceBankModels.kt",
     lambda s: 'SHARD_VERSION = "v3630"' in s),
    ("گزینه‌های خالی → تشریحی", "app/src/main/java/ir/exam/app/ui/bank/ReferenceBankMapper.kt",
     lambda s: "optionsBlank && !hasOptionImages" in s),
    ("آیکن‌های AutoMirrored", "app/src/main/java/ir/exam/app/ui/bank/ReferenceBankDialog.kt",
     lambda s: "Icons.AutoMirrored.Outlined.ArrowBack" in s and "Icons.Outlined.ArrowBack" not in s),
    ("راهنمای سطر بی‌متن", "app/src/main/java/ir/exam/app/ui/bank/ReferenceBankDialog.kt",
     lambda s: "در فهرست این پایه نیست" in s),
    ("سایت: plainQuestion", "site/src/refbank.js", lambda s: "function plainQuestion(html)" in s),
    ("ابزار ترمیم شارد", "scripts/repair_reference_bank_text.py", lambda s: "--local-dir" in s),
    ("تست V363", "app/src/test/java/ir/exam/app/V363_ReferenceBankTextTest.kt", None),
]

HEADER = """
V363 — نصب‌کنندهٔ خودکفا (نسخهٔ ۳)
  پچ داخل خودِ فایل است · SHA-256: {sha}
  حجم پچ: {size} بایت · نسخهٔ هدف: {version}
""".format(sha=PATCH_SHA256[:16] + "…", size=PATCH_BYTES, version=VERSION_WANTED)


def is_artifact(name):
    return name in ARTIFACT_NAMES or name.lower().endswith(ARTIFACT_SUFFIXES)


def run(args, cwd):
    proc = subprocess.run(args, cwd=str(cwd), capture_output=True, text=True)
    return proc.returncode, ((proc.stdout or "") + (proc.stderr or "")).strip()


def probe(repo):
    rows = []
    for label, rel, check in MARKERS:
        path = repo / rel
        if not path.is_file():
            rows.append((False, label, "فایل نیست"))
            continue
        if check is None:
            rows.append((True, label, "هست"))
            continue
        try:
            text = path.read_text(encoding="utf-8")
        except OSError as exc:
            rows.append((False, label, "خواندن نشد: %s" % exc))
            continue
        good = check(text)
        rows.append((good, label, "هست" if good else "نیست"))
    return rows


def upstream_refs(repo):
    refs = []
    code, up = run(["git", "rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}"], repo)
    if code == 0 and up.strip():
        refs.append(up.strip())
    for ref in ("origin/staging", "origin/main"):
        if ref not in refs:
            refs.append(ref)
    return refs


def exists_upstream(repo, path, refs):
    for ref in refs:
        code, _ = run(["git", "cat-file", "-e", "%s:%s" % (ref, path)], repo)
        if code == 0:
            return True
    return False


def classify(repo, refs):
    """تغییرات را جدا می‌کند؛ فایل‌های اصلیِ مخزن هرگز «مزاحم» حساب نمی‌شوند."""
    _, out = run(["git", "status", "--porcelain=v1", "-z"], repo)
    artifacts, real = [], []
    for entry in [e for e in out.split("\0") if e.strip()]:
        path = entry[3:]
        if not path:
            continue
        status = entry[:2].strip()
        upstream_file = exists_upstream(repo, path, refs)
        if is_artifact(pathlib.Path(path).name) and not upstream_file:
            artifacts.append((status, path))
        else:
            real.append((status, path))
    return artifacts, real


def try_apply(repo, patch_path):
    attempts = [
        ("git apply", ["git", "apply", "--check", str(patch_path)], ["git", "apply", str(patch_path)]),
        ("git apply --ignore-whitespace",
         ["git", "apply", "--check", "--ignore-whitespace", str(patch_path)],
         ["git", "apply", "--ignore-whitespace", str(patch_path)]),
        ("git apply --3way",
         ["git", "apply", "--check", "--3way", str(patch_path)],
         ["git", "apply", "--3way", str(patch_path)]),
    ]
    last = ""
    for name, check_cmd, apply_cmd in attempts:
        code, out = run(check_cmd, repo)
        if code == 0:
            code2, out2 = run(apply_cmd, repo)
            if code2 == 0:
                return True, name, out2
            last = "%s: %s" % (name, out2)
            continue
        last = "%s: %s" % (name, (out.splitlines() or ["خطا"])[0])
    code, out = run(["patch", "-p1", "--forward", "--batch", "--fuzz=2", "-i", str(patch_path)], repo)
    if code == 0:
        return True, "patch -p1 --fuzz=2", out
    return False, "هیچ‌کدام", (last + "\n" + out).strip()


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--repo", default="", help="پوشهٔ مخزن (پیش‌فرض: پوشهٔ همین فایل)")
    ap.add_argument("--commit", action="store_true")
    ap.add_argument("--push", action="store_true")
    ap.add_argument("--keep-artifacts", action="store_true")
    ap.add_argument("--message", default="V363 - reference bank question text in every grade (staging)")
    args = ap.parse_args()

    print("=" * 70)
    print(HEADER.strip())
    print("=" * 70)

    patch_bytes = base64.b64decode("".join(PATCH_B64.split()))
    digest = hashlib.sha256(patch_bytes).hexdigest()
    print("بررسی سلامت پچ داخلی: ", end="")
    if digest != PATCH_SHA256 or len(patch_bytes) != PATCH_BYTES:
        print("❌ خراب است (فایل کامل دانلود نشده؟) — دوباره دانلود کنید.")
        return 2
    print("✅ سالم (%d بایت)" % len(patch_bytes))

    here = pathlib.Path(__file__).resolve().parent
    repo = pathlib.Path(args.repo).expanduser().resolve() if args.repo else here
    if not (repo / ".git").exists():
        inside = [p for p in here.iterdir() if p.is_dir() and (p / ".git").exists()]
        if len(inside) == 1:
            repo = inside[0]
        elif not inside:
            print("\n❌ مخزن پیدا نشد. یا این فایل را داخل پوشهٔ پروژه بگذارید،")
            print("   یا با --repo مسیرش را بدهید، مثلاً:")
            print("   python3 V363_install.py --repo /mnt/c/Users/Hashem/Downloads/exam-app-kotlin")
            return 2

    code, _ = run(["git", "rev-parse", "--is-inside-work-tree"], repo)
    if code != 0:
        print("\n❌ این پوشه مخزن گیت نیست: %s" % repo)
        return 2

    # تغییرات «فقط مجوز فایل» (مثل gradlew روی /mnt/c) نباید مانع کار شود.
    _, mode_only = run(["git", "diff", "--summary"], repo)
    mode_only = [ln for ln in mode_only.splitlines() if ln.strip()]
    if mode_only and all(ln.strip().startswith("mode change") for ln in mode_only):
        run(["git", "config", "core.fileMode", "false"], repo)
        print("\nℹ️ تفاوت‌های فقط-مجوز فایل نادیده گرفته شد (core.fileMode=false).")

    _, branch = run(["git", "rev-parse", "--abbrev-ref", "HEAD"], repo)
    _, head = run(["git", "log", "--oneline", "-1"], repo)
    _, last = run(["git", "log", "--oneline", "-6"], repo)
    print("\nمخزن      : %s" % repo)
    print("شاخه      : %s" % branch)
    print("آخرین کامیت: %s" % head)
    print("\nکامیت‌های آخر:")
    for line in last.splitlines():
        print("   " + line)

    _, stat = run(["git", "show", "--stat", "--oneline", "--format=%h %s", "HEAD"], repo)
    inside = [ln for ln in stat.splitlines()[1:] if ln.strip()]
    print("\nمحتوای کامیت آخر:")
    print("\n".join("   " + ln for ln in inside[:10]) if inside else "   (خالی)")

    refs_all = upstream_refs(repo)
    artifacts, real = classify(repo, refs_all)
    if artifacts:
        print("\nفایل‌های مزاحمِ کامیت‌نشده (نادیده): " + "، ".join(p for _, p in artifacts[:6]))

    before = probe(repo)
    done = sum(1 for ok, _, _ in before if ok)

    # اگر تغییرات واقعی هست ولی همهٔ نشانه‌ها کامل‌اند، یعنی همان پچ اعمال شده و
    # فقط کامیت نشده است → باید کامیت شود، نه اینکه خطا بدهد.
    pending_is_patch = bool(real) and done == len(before)
    if real and not pending_is_patch:
        print("\n❌ تغییرات واقعیِ کامیت‌نشده:")
        for status, path in real[:10]:
            print("   · %s  [%s]" % (path, status))
        print("   اول آن‌ها را کامیت یا stash کنید.")
        return 3
    if pending_is_patch:
        print("\nℹ️ پچ اعمال شده ولی کامیت نشده است؛ اگر --commit بدهید همان کامیت می‌شود.")
    else:
        print("\nتغییرات کامیت‌نشدهٔ واقعی: هیچ ✅")
    print("\nنشانه‌های V363 در کد: %d از %d" % (done, len(before)))
    for ok, label, detail in before:
        print("   %s %s — %s" % ("✅" if ok else "❌", label, detail))

    applied = False
    if done == len(before):
        print("\n🎉 پچ از قبل کامل روی کد نشسته است؛ نیازی به اعمال نیست.")
    else:
        tmp = pathlib.Path(tempfile.mkdtemp(prefix="v363-"))
        patch_path = tmp / "V363.patch"
        patch_path.write_bytes(patch_bytes)
        print("\nاعمال پچ…")
        ok, method, detail = try_apply(repo, patch_path)
        print("روش اعمال: %s" % method)
        if not ok:
            print("❌ اعمال نشد. جزئیات:")
            print(detail[:1200])
            run(["git", "reset", "--hard", "HEAD"], repo)
            run(["git", "clean", "-fdq"], repo)
            patch_path.unlink(missing_ok=True)
            print("↩️ مخزن به حالت قبل برگشت.")
            return 1
        applied = True
        after = probe(repo)
        done2 = sum(1 for ok2, _, _ in after if ok2)
        print("\nنشانه‌های V363 بعد از اعمال: %d از %d" % (done2, len(after)))
        for ok2, label, d in after:
            print("   %s %s — %s" % ("✅" if ok2 else "❌", label, d))
        patch_path.unlink(missing_ok=True)
        if done2 != len(after):
            print("\n❌ اعمال شد ولی کامل نیست؛ کامیت نمی‌کنم.")
            return 1
        print("\n✅ پچ کامل و سالم اعمال شد.")

    removed = []
    if not args.keep_artifacts:
        refs = upstream_refs(repo)
        _, files = run(["git", "ls-files"], repo)
        self_name = pathlib.Path(__file__).name
        for path in [ln for ln in files.splitlines() if ln.strip()]:
            if not is_artifact(pathlib.Path(path).name) or exists_upstream(repo, path, refs):
                continue
            if pathlib.Path(path).name == self_name:
                continue          # خودِ نصب‌کننده پاک نمی‌شود
            code, _ = run(["git", "rm", "--cached", "-q", path], repo)
            if code == 0:
                (repo / path).unlink(missing_ok=True)
                removed.append(path)
        artifacts2, _ = classify(repo, refs)
        for _, path in artifacts2:
            target = (repo / path).resolve()
            if target.name == pathlib.Path(__file__).name:
                continue
            target.unlink(missing_ok=True)
            removed.append(path)
        if removed:
            print("\n🧹 از مخزن بیرون رفت: " + "، ".join(sorted(set(removed))))

    if not args.commit:
        print("\nبدون کامیت تمام شد. برای ثبت:")
        print("   python3 %s --commit --push" % pathlib.Path(__file__).name)
        return 0

    run(["git", "add", "-A"], repo)
    # خودِ نصب‌کننده هرگز وارد کامیت نمی‌شود
    run(["git", "reset", "-q", "--", pathlib.Path(__file__).name], repo)
    _, still = run(["git", "ls-files", "--error-unmatch", pathlib.Path(__file__).name], repo)
    if still.strip():
        run(["git", "rm", "--cached", "-q", "--", pathlib.Path(__file__).name], repo)
    shown = []
    for name, value in (("user.name", "Hashem Amiri"), ("user.email", "hashem@local")):
        code, _ = run(["git", "config", name], repo)
        if code != 0 or not _:
            shown += ["-c", "%s=%s" % (name, value)]
    code, out = run(["git"] + shown + ["commit", "-m", args.message], repo)
    print("\nکامیت: " + ("موفق ✅" if code == 0 else "ناموفق ❌"))
    if out:
        print("   " + out.splitlines()[0])
    _, head2 = run(["git", "log", "--oneline", "-1"], repo)
    _, version = run(["cat", "text/APP_VERSION.txt"], repo)
    print("   HEAD : %s" % head2)
    print("   نسخه : %s" % version)

    if args.push:
        code, out = run(["git", "push", "origin", "HEAD"], repo)
        print("\npush: " + ("موفق ✅" if code == 0 else "ناموفق ❌"))
        for line in out.splitlines()[-4:]:
            print("   " + line)

    print("\n" + "=" * 70)
    print("گام بعدی: تب Actions → اجرای جدیدترین کامیت")
    print("انتظار: APP_VERSION_NAME: 1.03.93 و 1756 tests بدون failed")
    print("=" * 70)
    return 0


